API Gateway / FHIR Facade Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("API Gateway / FHIR Facade Container", "API Gateway / FHIR Facade Container") {
    Component("API Gateway Handler", "API Gateway Handler", "Custom FHIR Facade", "Manages incoming HTTPS/TLS 1.3 requests from patients, staff, and external systems, routing them appropriately.")
    Component("FHIR Facade Router", "FHIR Facade Router", "Apache Camel", "Handles payload transformation, routing, and translation between custom payloads and HL7 FHIR standards.")
    Component("Auth Validator", "Auth Validator", "OAuth2 / OpenID Connect Client", "Communicates with the Security/Auth Proxy Container to validate incoming requests and user sessions.")
}

Rel("API Gateway Handler", "Auth Validator", "Validates requests via OAuth2 / OpenID Connect", "")
Rel("API Gateway Handler", "FHIR Facade Router", "Forwards requests for routing and payload transformation", "")
Rel("FHIR Facade Router", "Domain Services Containers", "Route traffic via gRPC / REST over TLS (mTLS)", "gRPC / REST over TLS (mTLS)")
Rel("FHIR Facade Router", "External Labs / Imaging Systems", "Communicate via HTTPS, HL7 FHIR APIs", "HTTPS, HL7 FHIR")

@enduml

Security/Auth Proxy Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Security/Auth Proxy Container container

Container_Boundary(Security_Auth_Proxy_Container, "Security/Auth Proxy Container") {
    Component(OAuth2_OIDC_Reverse_Proxy, "OAuth2 / OIDC Reverse Proxy", "Envoy", "Validates requests, authenticates sessions, enforces mTLS, rate-limiting, and request schema validation.")
    Component(Token_Validator_Component, "Token Validator Component", "OAuth2 / OpenID Connect with JWKS", "Stateless authentication using locally validated short-lived JWTs to minimize IdP bottlenecks.")
}

Rel(OAuth2_OIDC_Reverse_Proxy, Token_Validator_Component, "Validates incoming tokens and authenticates sessions", "OAuth2 / OIDC")

@enduml

Async Event Bus Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Async_Event_Bus_Container, "Async Event Bus Container") {
    Component(Event_Publisher, "Event Publisher", "Kafka / RabbitMQ Producer Client", "Publishes asynchronous events from domain services with AES-256 encryption.")
    Component(Event_Broker_Core, "Event Broker Core", "Apache Kafka / RabbitMQ", "Handles high throughput, message routing, and cross-site mirroring for disaster recovery.")
    Component(Event_Consumer, "Event Consumer", "Kafka / RabbitMQ Consumer Client", "Consumes asynchronous events for downstream domain processing and auditing.")
}

Rel(Event_Publisher, Event_Broker_Core, "Sends encrypted event messages over TLS", "TLS")
Rel(Event_Broker_Core, Event_Consumer, "Delivers queued asynchronous events", "")
@enduml

